"""Build detailed audited interpretation from independently verified tables."""
from pathlib import Path
import hashlib
import json
import re
import pandas as pd

OUT=Path(__file__).resolve().parent
BASE=OUT.parent


def read(p):return json.loads(Path(p).read_text())
def md_table(columns,rows):
    return '\n'.join(['| '+' | '.join(columns)+' |','| '+' | '.join(['---']*len(columns))+' |']+
        ['| '+' | '.join(str(v) for v in row)+' |' for row in rows])
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def main():
    audit=read(OUT/'audit_summary.json');check=audit['checks'];a=pd.read_csv(OUT/'adaptation_summary.csv').set_index('arm')
    events=pd.read_csv(OUT/'adaptation_events.csv');heads=pd.read_csv(OUT/'headroom_summary.csv');dep=pd.read_csv(OUT/'deployment_audit.csv')
    support=pd.read_csv(OUT/'support_audit.csv');eff=pd.read_csv(OUT/'ofa_learning_efficiency_corrected.csv');curves=pd.read_csv(OUT/'ofa_learning_curves_corrected.csv')
    order=['F0','F1','F2_1','F2_5','F2_20','F3','F4','B_supervised','B_teacher_label','B_supervised_SGD20','Qbase','Q0','Q1','Q2','Q3']
    names={'F0':'Frozen FP parent','F1':'Two-coordinate calibration','F2_1':'Head-only soft KD, 1 step','F2_5':'Head-only soft KD, 5 steps','F2_20':'Head-only soft KD, 20 steps','F3':'Uniform residual ridge','F4':'Reliability-weighted ridge','B_supervised':'One-chip supervised ridge','B_teacher_label':'One-chip teacher+label ridge','B_supervised_SGD20':'One-chip supervised SGD, 20 steps','Qbase':'Frozen PTQ simulation','Q0':'Uniform, gamma=0','Q1':'Reliability, gamma=0','Q2':'Uniform, gamma=1','Q3':'Reliability, gamma=1'}
    fp32=dep[dep.precision=='FP32'].iloc[0];fp16=dep[dep.precision=='FP16'].iloc[0]
    saving=100*(1-fp16.artifact_bytes/fp32.artifact_bytes);slower=100*(fp16.p50_ms/fp32.p50_ms-1)
    body=["# FloodDistill v8: audited results, detailed analysis and required next work",
        "12 October 2026, Europe/Berlin. This report preserves the frozen worker outputs and corrects two reporting problems in separate audit tables. It distinguishes observations, plausible explanations and proposed next experiments.",
        "**Status. All scheduled work is complete.** The worker launched at 14:55:27 CEST and finished at 15:01:05 CEST; final collection completed at 15:01:06 CEST. A live host check at 19:23 CEST confirmed that PID1493699 had exited and there were no GPU compute processes on either RTX4090. All eight worker jobs completed, all 180 adaptation rows are present, and the failure ledger is empty. No experiment remains queued by this finished worker.",
        f"The programme spent **{check['incremental_hours']:.6f} GPU-command hours** ({60*check['incremental_hours']:.2f} minutes), including both real smokes. Cumulative capacity-programme spend is **{check['cumulative_hours']:.6f} hours**, leaving **{check['remaining_cumulative_hours']:.6f} hours** under the 30-hour limit. Worker wall duration was {check['worker_wall_minutes']:.2f} minutes. This is elapsed GPU-tagged command time, not utilization, energy or training-only time. Shared saved teacher hard predictions, tiny student forwards and small cached head fits explain the short workload; no new foundation-model fine-tuning was run. The remaining budget is not an instruction to restart the finished manifest or spend it automatically.",
        "**Research conclusion. Useful complementary teacher information remains, but the proposed reliability-weighted single-solve update did not absorb it successfully in this pilot.** Uniform ridge loses 0.38pp mean query mIoU; reliability weighting increases the loss to 0.55pp. Twenty cached head-only soft-KD steps give a small descriptive gain of 0.079pp, with worsening episodes retained. The quantization penalty reduces some harm but does not make the combined method beat its simpler controls. R4 remains an established small deployed graph; v8 supplies a reproducible negative adaptation result, not a successful new selective-distillation method.",
        "## Execution and integrity",
        f"The CPU audit verified **{check['frozen_inputs']} frozen input hashes**, all six child-manifest hashes and eight terminal job attempts. All **180 adapted checkpoint hashes** match their rows; {check['unchanged_extractor_tensor_comparisons']:,} extractor/buffer tensor comparisons confirm that only the final classifier changed. It independently recomputed {check['recomputed_ridge_calibration_solves']} calibration/ridge solves and all 180 scores from integer confusion counts. It checked the pixel-accuracy identity in {check['joint_event_cells_recomputed']} event/comparator cells. No integrity mismatch was found. Real FP/Q folding errors were at most 2.87e-6 margin units, and normal-equation gradient residuals were below 1e-8.",
        "The checks validate their stated numerical/artifact properties. They do not establish population generalization, novelty, field readiness, or the correctness of every prose label. Two reporting problems were found despite successful worker receipts:",
        "- The learning-curve parser searched for `ep` without a word boundary and matched it inside `step`. Every recorded validation epoch was one epoch too early; selected/final flags were consequently wrong. Corrected tables parse the zero-based epoch `step` explicitly and add one. The 798 observations now identify all 32 selected and 32 final checkpoints. Original outputs are retained.",
        "- Deployment backend metadata was captured after the source loader reset matmul precision to `medium` and matmul TF32 to true. The earlier timing code configured TF32 false and matmul `highest`; CPU replay verified that the reset happens after tracing and before source accuracy. There was no contemporaneous GPU flag receipt at timing. The FP16 backend helper also hard-coded FP32 dtype labels. Saved artifact parameters independently verify FP16 execution weights. The audited report separates the configured timing path, post-accuracy flags and actual artifact dtype.",
        "See `analysis_20261012/audit_summary.json`, `solver_audit.csv`, `deployment_audit.csv` and `backend_phase_replay.json` for evidence. Frozen code, manifests and the automatic report are unchanged.",
        "## What was tested and what the experimental units are",
        "The teacher is the fixed task-adapted Prithvi checkpoint; it inherits 252 labelled source-training scenes. R4 has 12,230 parameters and a 16-channel affine final two-class head. The experiment optimizes 17 effective margin coordinates, or two calibration coordinates, and folds the correction into existing weights. No deployed feature channel or post-adaptation teacher call is added. Extractors and BN buffers stay frozen in eval mode.",
        "Three WorldFloods events were chosen deterministically by metadata: EMSR264, EMSR286 and EMSR333. One map per event supplies 51, 34 and 7 query tiles, respectively: **92 query tiles**, not a full adapted-benchmark evaluation. Each event has two geographically disjoint one-chip support draws. Parents42/64 yield12 event/parent/support episodes per arm. Frozen baselines repeated across draws are the same parent predictions, not additional trained models. Tables average within event across the four paired seed/support outcomes, then weight the three events equally. No population CI is estimated from millions of correlated pixels.",
        "Source-only selection used two disjoint S11-validation development pairs, Ghana and India. Both parents selected lambda0.1; SGD selected LR0.001 for seed42 and0.1 for seed64. The two development query chips supplied 517,329 unique valid labelled pixels for hyperparameter selection, shared across arms/parents; support reference values were used only for offline diagnosis. Source labels are a disclosed selection budget. Query labels from the target events never fit an update or choose a checkpoint. Every external set is already research-exposed, so this is exploratory transfer.",
        "The restored original N2500 membership has zero replacements and SHA256 `1ac4ef17efae3ebb0d3fb8daad38b4541ef04627c07a60e1e2c42e00d2efbc60`. Historical generation-time byte identity is unavailable. TRAIN-only images set feature statistics and quantizer scales. R4 parents, teacher, split/order, normalization, masks, original activation versus repaired graph identities and the earlier V7 C3 negative result are preserved.",
        "## Does the teacher know useful corrections?",
        "Yes, it has correct predictions on some pixels where R4 is wrong. It also makes errors where R4 is correct. The unattainable label-aware oracle identifies remaining complementary information; it is not a deployable router. All table scores below are percentages and are descriptive means across the two student parents; the teacher is one fixed model. G/H are fractions of the same valid pixels, expressed here as percentages. G-H equals teacher-minus-student pixel accuracy, not their IoU difference."]
    h=heads[heads.comparator=='T|S']
    rows=[]
    for dataset in ['source_validation','s11','sturm','wf']:
        for agg in ['pooled_pixel_counts','equal_event']:
            v=h[(h.dataset==dataset)&(h.aggregation==agg)].iloc[0]
            rows.append([dataset,'Pooled' if agg.startswith('pooled') else 'Equal event',f'{100*v.G:.3f}',f'{100*v.H:.3f}',f'{100*v.teacher_water_IoU:.2f}',f'{100*v.student_water_IoU:.2f}',f'{100*v.oracle_water_IoU:.2f}'])
    body += [md_table(['Dataset','Average','G %','H %','Teacher water IoU','R4 water IoU','Oracle water IoU'],rows),
        "On WF, the oracle increases pooled water IoU from65.98 to68.24, about2.26pp; equal-event water IoU rises from47.95 to54.00, about6.06pp. Thus the teacher is neither a universally superior prediction nor devoid of useful corrections. WF pooled G is below H, while equal-event G is above H, and the teacher/R4 water-IoU ranking also reverses. Large events/pixel counts and equal-event means answer different questions. The STURM teacher has useful water corrections even though pooled pixel accuracy favors R4: class-conditional water correction rates are3.30–4.51%, versus0.63–0.84% harmful imitation on reference-water pixels. Precision, recall, IoU and pixel accuracy must remain separate.",
        "The teacher/MNDWI oracle on WF reaches73.86 pooled and61.40 equal-event water IoU, versus teacher64.32/50.54 and rule63.81/40.06. This points to considerable expert complementarity already available without a second foundation model. It does not show that an implementable confidence gate can find the correct expert, or that a tiny optical student can represent every correction. The two pairwise oracle tables do not establish a three-expert joint oracle. Full and known-overlap-excluded event/class counts are retained, with undefined empty unions omitted from event means.",
        "![Pooled and equal-event WF headroom must be distinguished.](analysis_20261012/headroom_estimands.png)",
        "## FP adaptation: controls and every worsening outcome",
        "mIoU is region overlap averaged across land/water classes, not pixel accuracy. Effects below are percentage points relative to the corresponding frozen parent. Positive/negative counts are descriptive episode counts; their twelve entries contain only three transfer events."]
    rows=[]
    for arm in order:
        v=a.loc[arm];rows.append([arm,names[arm],f'{v.mIoU_pct:.3f}',f'{v.delta_parent_pp:+.3f}',f'{v.water_delta_parent_pp:+.3f}',f'{int(v.positive_episodes)}/{int(v.negative_episodes)}'])
    body += [md_table(['Arm','Method','Query mIoU %','mIoU change pp','Water-IoU change pp','Better/worse episodes'],rows),
        "The reliability candidate F4 loses0.173pp against uniform F3,0.265pp against two-coordinate calibration, and0.630pp against F2_20. It does not exceed either a simple correction or conventional head-only KD. F2_20 improves seven episodes and worsens five; its maximum gain is0.597pp and minimum is−0.191pp. The modest average benefit is useful pilot evidence, not a demonstrated robust population gain. F2_5 improves nine episodes with a smaller average gain. There is no prospective promotion to larger training hidden in these outcomes.",
        "F4's event mean mIoU changes are−1.013pp on EMSR264,−0.804pp on EMSR286 and+0.162pp on EMSR333. The last event's small mIoU increase coexists with a water-IoU decrease of0.010pp; background improvement alone is insufficient for the flood/water objective. On EMSR264, F4 increases precision from64.89 to65.62% while reducing recall from44.55 to41.23%. On EMSR286 recall falls from82.44 to80.51%. All event means and paired controls are in the audited CSVs.",
        "![Mean paired effects and all three event effects. Q arms use their quantized parent comparator.](analysis_20261012/adaptation_control_effects.png)",
        "## Why the reliability proxy is a plausible cause of failure",
        f"An offline diagnostic on the six target support chips found **{audit['target_confident_stable_water_errors']:,} errors among {audit['target_confident_stable_water_pixels']:,} confident/stable reference-water pixels: {100*audit['target_confident_stable_water_error_fraction']:.2f}% were confidently predicted as land**. Confidence means max probability>=0.9; stability means absolute probability change<=0.05 under the frozen+2% gain. These are counted observations on six correlated chips, not independent trials. Source-development confident/stable water error is only184/219,915, about0.084%; this proxy changes reliability sharply under domain shift.",
        "The actual sampled reliability weights reinforce this concern. On EMSR264 support draw0, the average weight for incorrect water predictions exceeds the correct-water weight in both parents:0.631 versus0.439 for seed42,0.702 versus0.392 for64. Incorrect sampled water predictions receive81.6–82.2% of that chip's water-class weight. On EMSR333 draw0, corresponding weighted error shares are62.4–65.7%. Low sensitivity to a small radiometric change measures invariance, not truth. Land dominance can hide water misses in an overall confidence-accuracy summary.",
        "A second issue is support representativeness. Both EMSR286 support samples contain zero labelled water pixels despite query water IoU near81.61% for the parent. EMSR333's second support draw is also sampled entirely as land; the sparse EMSR264 second draw supplies only two water samples for seed42 and none for64. Support chips were selected without target outcomes, as required; these observations explain a possible support/query coverage problem without retroactively changing selection. Teacher-only and supervised fits can both learn the local operating point of mostly-land support and lose query recall. The observations support this hypothesis; they do not prove that label-free support selection is impossible or that all teacher corrections are unrepresentable.",
        "Numerical failure is not the explanation: cached features are finite, gradients/linear systems are valid, normal equations solve correctly and folded heads match their intended updates. Lambda0.1 was selected at the grid's upper boundary on source development. All teacher-only ridge/Q updates had eta1; the declared damping did not rescue or cause their negative effects. The supervised ridge arm alone required eta0.61–0.78. Ridge optimizes bounded logit residuals; SGD optimizes soft probability KD at temperature4. A comparison of the two does not isolate the linear solve from the objective or update magnitude. A future causal test must separate those factors.",
        "## One labelled chip: the tested fitting recipe failed",
        "The supervised ridge arm loses1.771pp mean mIoU; teacher+label ridge loses1.238pp. Mixing teacher targets improves the supervised-ridge control by0.533pp, yet the mixture remains0.884pp worse than supervised20-step SGD and below the frozen parent. No gain from the currently tested labelled-head recipe is established. This is not evidence that target annotation is worthless. Labelled fits inherit the teacher-only source-selected lambda/LR; they were not independently optimized for their supervised objective. A strong annotation-value claim therefore requires a separately source-tuned supervised baseline with equal selection/annotation opportunity.",
        f"Each episode receives one existing manually labelled benchmark support chip, with134,889–252,905 valid reference pixels, covering13.49–25.29km² on the10m grid. The six unique alternative support chips offer {audit['labels_available_six_unique_support_chips']:,} labelled pixels total, reused across parents/arms; do not multiply them into independent annotation datasets. Fitting uses2,474–4,013 spatially sampled pixels per chip, not every available labelled pixel. Report the accessible full-chip annotation budget and the sampled fit support separately. This is one labelled chip, not one labelled pixel; no new manual annotation was purchased.",
        "## Quantization: small penalty benefit, unsuccessful combined mechanism",
        "Qbase is fixed PTQ/fake-quant W4A8 backbone, W8A8 stem and FP32 head, calibrated on16 TRAIN chips. Q0–Q3 form the frozen2x2 reliability/penalty ablation. Scales are fixed; master arithmetic/tensors remain float32. No real low-bit kernels, packed integer artifact, QAT-trained backbone or low-bit latency result was established.",
        "Relative to Qbase, Q0/Q1/Q2/Q3 mean mIoU changes are−0.474/−0.810/−0.447/−0.717pp. Gamma1 helps uniform by0.027pp and reliability by0.093pp, but Q3 remains worse than Q0 by0.243pp and Q2 by0.270pp. The combined-arm claim fails its stated interpretation criterion. A small positive factorial interaction of about0.067pp is descriptive and does not override losses against simpler controls.",
        "The frozen quantized parent itself is only−0.016pp below FP in the three-event average, yet event changes are−1.240pp on EMSR264,−0.148pp on EMSR286 and+1.339pp on EMSR333. This cancellation shows why the average is insufficient. It is a simulation outcome and possible operating-point effect, not proof of trustworthy severe compression. The new Q point has no complete source-validation1/2/3pp frontier and no competent full-QAT comparison; those are prerequisites for a strong compression-method claim.",
        "## Adaptation cost and actual deployment",
        "Median solver/optimizer times are0.731ms for uniform ridge,0.737ms for weighted ridge and6.267ms for20-step KD. Shared cached teacher targets and features give SGD the same caching opportunity. The roughly8.5-times inner-optimizer difference is not an end-to-end acceleration claim. Recorded median component sums are58.1ms for ridge versus63.9ms for20-step KD, so teacher/features largely dominate that comparison.",
        "The field named `cold_end_to_end_seconds` sums measured reused-engine components. It omits teacher construction/checkpoint loading, input preparation/transfer before teacher timing, some feature transformations, head folding and artifact serialization; shared normalization/calibration are separately reported. Per-method memory also comes from a shared command process. Preserve the measured component times, but do not present them as a truly cold wall-clock or isolated memory comparison. A future full-pipeline benchmark must include those boundaries."]
    body.append(md_table(['Engine','Actual bytes','p50 / p95 ms','Incremental allocator MiB','Source mIoU %'],[[v.precision,f'{int(v.artifact_bytes):,}',f'{v.p50_ms:.4f} / {v.p95_ms:.4f}',f'{v.incremental_MiB:.3f}',f'{v.source_mIoU_pct:.6f}'] for v in dep.itertuples()]))
    body += [f"FP16 saves **{saving:.2f}% actual serialized bytes**, with source mIoU change−0.000236pp, but its observed p50 forward latency is **{slower:.2f}% slower** in these sessions. FP16 passes the descriptive1/2/3pp source quality-loss tolerances for this seed. It does not have a demonstrated throughput advantage. Both points are Pareto-relevant depending on storage versus workstation latency; repeated-session/edge performance and energy remain unmeasured. Static parameter counts or theoretical packing are not artifact/latency measurements.",
        "These are separate fresh processes, teacher unloaded, common1x6x512x512 input,20 warmups and100 synchronized forward timings. CPU-loaded artifact parameters verify pure FP16 versusFP32 storage. The incremental allocator peaks are isolated timing-phase measurements, unlike retained-tensor-contaminated V7 peaks. Post-source-score flags are cuDNN TF32false, matmul TF32true and precisionmedium; the timing code's configured strict phase has only code/CPU-replay evidence. Neither a comparison with earlier V7 latency nor an edge speedup should be inferred. Native INT8 remains unsupported under the inherited TensorRT/runtime-driver combination; no repair or new install was attempted.",
        "## OFA efficiency recovered from real training, with corrected epochs",
        "The32 actual training wrappers provide798 validation observations, with original logs/checkpoint identities preserved. Inference commands containing `train` in their names were excluded by inspecting effective nested argv. Source-validation thresholds70/75/80/85% were fixed in advance. First crossings are observed at validation intervals; they are not interpolated or exact continuous crossing updates. Unreached thresholds stay censored. Logged scores have four-decimal precision, so threshold equality has that rounding limitation.",
        "For EfficientViT N100, all four seeds reach70% and75%: average first observed crossings are108/144 updates forLKD versus96/132 forOFA. Neither reaches80% or85%. Thus the observed low-data curves show a12-update earlier mean threshold crossing forOFA, within the12-update validation spacing. This is bounded update-efficiency evidence, not isolated sample efficiency or measured time-to-quality acceleration.",
        "At N2500, both methods first exceed80% at312 updates, the first source validation. At85%, LKD reaches in three of four seeds, with one censored; OFA reaches all four. Mean936 versus1482 among reached seeds is not a fair unconditional ranking because censoring differs. LightFormer85% crossings average2184LKD/2886OFA; MobileNet averages1794LKD/1482OFA. These mixed curves do not support universal OFA acceleration across backbones/budgets. Full-budget EfficientViT OFA retains its legacy all-pixels KL label, while the LKD wrapper uses valid-only; do not silently erase that policy distinction.",
        "Mean complete training-wrapper elapsed time is176.7sLKD versus182.1sOFA atN100;924.6 versus1073.7s for EfficientViTN2500;946.2 versus1084.2s forMobileNet;1064.4 versus1200.5s forLightFormer. Wrappers include teacher/head work plus terminal evaluation/checkpoint checks. Per-validation time stamps and isolated training phase timing are absent, so observed time-to-threshold is unavailable. AcrossN100/N2500, distinct scenes and total update budgets change together (300 versus7800 maximum updates); the curves cannot isolate sample efficiency.",
        "![Corrected update curves; dots mark the actual selected checkpoints. Timing at intermediate observations is unavailable.](analysis_20261012/ofa_learning_curves_corrected.png)",
        "## What must be done next",
        "1. **Use the corrected reporting now.** Cite the audited epoch/crossing tables, actual deployment dtypes and explicit timing phases. Keep original reports/results as historical artifacts. Add selection/label budgets, map-level pilot scope, exposed external-set disclosure and all failed scientific effects. Record the V7 continuation failure and the V8 reliability/combined-Q failures together; do not promote either into a positive novelty claim. Parser correction and the present integrity audit are complete.",
        "2. **Make the next experiment diagnose a cause.** Before more full-network KD, compare confidence-only versus stability-weighted correction, equal objective/update-size controls, and label-free support-coverage rules designed on source development only. Separate loss objective, linear solver and update magnitude. Include a source-selected conservative/no-update control. The current gain+2% proxy is demonstrably overconfident on some water misses; repeating F4 unchanged is not justified. A support set selected after looking at these query outcomes would create new tuning bias and cannot be called prospective.",
        "3. **Strengthen the small-student deployment branch.** Retain R4 FP32/FP16 as working artifacts, then require a competent existing QAT control, source-quality tolerances, all-event accuracy and a compatible native engine before claiming extreme low-bit deployment. Log flags/dtypes at both timing and accuracy boundaries. Benchmark true cold/reused-engine adaptation cost and repeat workstation timings; measure target edge hardware only when it exists. Avoid spending the whole remainder on driver/backend repair. The severely poor EMSR333 parent water IoU (~8.43%) remains an application limitation despite strong source validation.",
        "4. **Acquire missing evidence before manuscript closure.** The actual reviewer letter and `test.txt` were not located; concern IDs currently inherit prompt summaries. Independent verified dry scenes are still needed for real dry false-alarm claims. A second-teacher screen needs an installed task-adapted water head, acquisition dates/licence, verified co-registration and compatible SAR/optical preprocessing. Matching names or a pretrained encoder are insufficient. Any new teacher/data preparation or compute reallocation needs a separately bounded task; none was scheduled here.",
        "5. **Confirm on valid independent transfer units.** Use new disjoint support/query episodes and, if possible, a prospectively reserved event set. Keep the original3-event pilot descriptive, inspect every worsening case and distinguish training-seed from event uncertainty. All current external benchmarks are research-exposed; no re-freeze makes them untouched. A reliability or compression interaction needs replication before a strong method claim. Extra labelled selection must have equal-label direct-student controls.",
        "The most defensible present contribution is a carefully audited tiny-student accuracy/storage tradeoff plus evidence that useful teacher corrections and harmful imitation coexist. V8 identifies why a plausible confidence/stability update is unsafe in this regime and supplies matched negative controls. The next method must solve that demonstrated failure and beat conventional KD/calibration at equal cost before it can support a new accuracy-method contribution. Known ridge-based adaptation and multimodal foundation-assisted flood mapping remain prior art; a bounded literature check is not novelty clearance.",
        "## Deliverables and reproduction",
        "The immutable initial manifest, status/ledger, job/launch receipts and original180 rows remain in the run directory. New audited outputs are `analysis_20261012/audit_summary.json`, `adaptation_summary.csv`, `adaptation_events.csv`, `paired_controls.csv`, `joint_errors_by_class.csv`, `headroom_summary.csv`, `support_audit.csv`, `reliability_audit.csv`, `solver_audit.csv`, `ofa_learning_curves_corrected.csv`, `ofa_learning_efficiency_corrected.csv`, `deployment_audit.csv` and the three figures. `reviewer_response_map.md` retains point-to-evidence mapping with the missing-letter qualification.",
        "CPU reproduction uses the installed esi environment; it performs no GPU job or experiment relaunch:",
        "```bash\nR=/home/schmalstieg/repos/FloodDistill/experiments/revision/research_v8_20261012T123202Z\nP=/home/schmalstieg/miniconda3/envs/esi/bin/python\nCUDA_VISIBLE_DEVICES='' OMP_NUM_THREADS=2 OPENBLAS_NUM_THREADS=2 \\\n  \"$P\" \"$R/analysis_20261012/audit_analysis.py\"\nCUDA_VISIBLE_DEVICES='' \"$P\" \"$R/analysis_20261012/build_report.py\"\n```",
        "No further experiments are running, reserved or automatically queued. Remaining research work above is an outline, not a claim of completed validation."]
    text='\n\n'.join(body)+'\n'
    text=re.sub(r'\b(PID|lambda|Lambda|eta|LR|from|to|about|and|versus|by|only|with|than|seed|draw|gamma|Gamma|temperature|mean|at|near|teacher|rule|all|LightFormer|MobileNet|loses|are|uses|covering|on|of|roughly|sums|frozen|both|sampling|episodes|steps|width|maximum|two|three|each|the)(?=\d)',r'\1 ',text)
    text=re.sub(r'\b(are|is|from|to|by|versus|and|mean)(?=[−+])',r'\1 ',text)
    text=re.sub(r'(?<=\d)(m|km²)(?=\b|²)',r' \1',text)
    text=re.sub(r'(?<=\d)(pp|ms|km²)\b',r' \1',text)
    text=text.replace('EfficientViTN2500','EfficientViT N2500').replace('forLKD','for LKD').replace('forOFA','for OFA').replace('updates forLKD','updates for LKD').replace('updates forOFA','updates for OFA').replace('sLKD',' s LKD').replace('sOFA',' s OFA').replace('parents42/64','parents 42/64').replace('Parents42/64','Parents 42/64').replace('supervised20-step','supervised 20-step').replace('of16','of 16').replace('20 warmups and100','20 warmups and 100').replace('with134,889','with 134,889').replace('the12-update','the 12-update').replace('original3-event','original 3-event').replace('source-validation1/2/3','source-validation 1/2/3')
    target=BASE/'report_v8_codex_audit_20261012.md';target.write_text(text)
    receipt=dict(report_path=str(target),report_sha256=sha(target),audit_summary_sha256=sha(OUT/'audit_summary.json'),
        evidence_tables={p.name:sha(p) for p in OUT.glob('*.csv')},analysis_sources={p.name:sha(p) for p in OUT.glob('*.py')},
        frozen_manifest_sha256=sha(BASE/'manifest_initial.json'),preserved_worker_report_sha256=sha(BASE/'report.md'),
        audit_errors=audit['errors'],issues_disclosed=len(audit['issues']))
    (OUT/'report_receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(target)


if __name__=='__main__':main()
